-- Consolidated final authored migration, including door, placeholder and paper-model repairs.
-- Normalized to one transaction; temporary-table guards enforce strict-mode failure.
SET SESSION sql_mode=CONCAT_WS(',',@@SESSION.sql_mode,'STRICT_ALL_TABLES');
START TRANSACTION;
-- XP = configurable approved PEQ-style default; no unverified achievement rewards.
CREATE TEMPORARY TABLE _shard_guard (ok TINYINT NOT NULL);
DELETE FROM task_activities WHERE taskid=910020;
