UPDATE zone SET min_status=0 WHERE zoneidnumber=754 AND short_name='kaelshard'AND version=0 AND min_status=80 AND min_level=0 AND max_level=255 AND expansion=19 AND ruleset=1 AND COALESCE(flag_needed,'')='';
UPDATE zone SET min_status=0 WHERE zoneidnumber=755 AND short_name='eastwastesshard'AND version=0 AND min_status=80 AND min_level=0 AND max_level=255 AND expansion=19 AND ruleset=1 AND COALESCE(flag_needed,'')='';
