-- Upgrade existing optional criterion semantics as well as fresh insertions.
-- Correct criterion semantics to match the admitted component_type2 definition.
-- This does not independently prove the original May2013 required/optional shape.
-- MariaDB10.2.1+; run without --force. No player-state changes or grants.
SET SESSION check_constraint_checks=1;
DROP TEMPORARY TABLE IF EXISTS _shards_optional_guard;
CREATE TEMPORARY TABLE _shards_optional_guard (
 name VARCHAR(80) NOT NULL PRIMARY KEY,
 ok TINYINT NOT NULL,
 CONSTRAINT shards_optional_guard_ok CHECK(ok=1)
) ENGINE=InnoDB;
 NOT EXISTS(SELECT 1 FROM achievement_criteria WHERE achievement_id=2075225 AND component_type=2 AND component_id IN(2075226,2075228) AND
  (event_type<>4 OR progress_mode<>3 OR behavior NOT IN(0,1) OR required_count<>1 OR enabled<>1 OR target_id2<>0 OR target_value<>0 OR
   target_id<>CASE component_id WHEN 2075226 THEN 910020 ELSE 910022 END OR component_sequence<>CASE component_id WHEN 2075226 THEN 2 ELSE 4 END)));
UPDATE achievement_criteria SET behavior=1 WHERE achievement_id=2075225 AND component_type=2 AND component_id IN(2075226,2075228)
 AND event_type=4 AND progress_mode=3 AND behavior=0 AND required_count=1 AND enabled=1
 AND target_id=CASE component_id WHEN 2075226 THEN 910020 ELSE 910022 END;
DROP TEMPORARY TABLE _shards_optional_guard;

COMMIT;
